INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3565, 'កង់យោងមួយមានកាំ \(60\ \text{m}\)។ អ្នកជិះនៅជាប់គែមធ្វើដំណើរបានប៉ុន្មានម៉ែត្រក្នុង \(1\) ជុំ? (\(\pi = 3.14\))', NULL, '["\\(753.6\\ \\text{m}\\)", "\\(120\\ \\text{m}\\)", "\\(376.8\\ \\text{m}\\)", "\\(188.4\\ \\text{m}\\)"]', 2, NULL, 3, 'mcq', '\(2 \times 3.14 \times 60 = 376.8\)។', 'រង្វង់', 'hard', 1, '7', 'រង្វង់', NULL, 0);
