INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3572, 'គណនាផ្ទៃក្រឡា ប្រវែងធ្នូ និងបរិមាត្រនៃចម្រៀកថាសកាំ \(21\ \text{cm}\) និងមុំផ្ចិត \(60^\circ\) (យក \(\pi \approx \dfrac{22}{7}\))។', NULL, '[]', 0, NULL, 5, 'writing', '\(\mathcal{A} = \pi R^2 \times \dfrac{60}{360} = \dfrac{1}{6} \times \dfrac{22}{7} \times 21^2 = 231\ \text{cm}^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3573, 'កង់យោងមួយមានកាំ \(125\ \text{feet}\) ឬ \(38.1\ \text{m}\) (\(1\ \text{foot} = 30.48\ \text{cm}\))។ ក. អ្នកជិះនៅគែមកង់ធ្វើដំណើរប៉ុន្មានម៉ែត្រក្នុង \(1\) ជុំ? ខ. ក្នុង \(5\) ជុំ? (យក \(\pi = 3.14\))', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(p = 2 \times 3.14 \times 38.1 = 239.268\ \text{m}\) (3 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3574, 'កង់រថយន្តមួយមានកាំ \(28\ \text{dm}\)។ ក. បរិមាត្រកង់ (\(\pi = \dfrac{22}{7}\))។ ខ. រថយន្តធ្វើដំណើរ \(1.1\ \text{km}\) កង់វិលប៉ុន្មានជុំ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(p = 2 \times \dfrac{22}{7} \times 28 = 176\ \text{dm} = 17.6\ \text{m}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3575, 'នំខេកមូលមួយកាំ \(15\ \text{cm}\) ត្រូវកាត់ជា \(6\) ចម្រៀកស្មើគ្នា (យក \(\pi = 3.14\))។ ក. ផ្ទៃក្រឡានំទាំងមូល។ ខ. ផ្ទៃក្រឡាចម្រៀកមួយ។ គ. មុំផ្ចិតនៃចម្រៀកមួយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(3.14 \times 225 = 706.5\ \text{cm}^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3576, 'ក្រុមហ៊ុនធ្វើតុរង្វង់ទំហំអង្កត់ផ្ចិត \(1.2\ \text{m}\)។ ក. ផ្ទៃក្រឡាតុ (\(\pi = 3.14\))។ ខ. បិទបន្ទះឈើគែមតុជុំវិញ ត្រូវការប៉ុន្មានម៉ែត្រ? គ. បិទឈើមួយម៉ែត្រថ្លៃ \(6\,000\) ៛ ថ្លៃសរុប?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(R = 0.6\) ; \(\mathcal{A} = 3.14 \times 0.36 = 1.1304\ \text{m}^2\) (2 ពិន្ទុ)
